1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/hex"
6		"encoding/json"
7		"errors"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12		"sort"
13		"strings"
14		"syscall"
15		"time"
16	)
17	
18	type Entry struct {
19		Name      string    `json:"name"`
20		Digest    string    `json:"digest"`
21		Size      int64     `json:"size"`
22		CreatedAt time.Time `json:"createdAt"`
23	}
24	
25	type index struct {
26		Entries map[string]Entry `json:"entries"`
27	}
28	
29	type Store struct{ root string }
30	
31	func New(root string) *Store { return &Store{root: root} }
32	
33	// withLock serializes access to the repository across cooperating processes.
34	// Mutating operations pass exclusive=true; readers take a shared lock. The
35	// lock is an flock on <root>/.lock, so it is released automatically if a
36	// process dies mid-operation and nothing can wait forever on a stale lock.
37	func (s *Store) withLock(exclusive bool, fn func() error) error {
38		if strings.TrimSpace(s.root) == "" {
39			return errors.New("root is required")
40		}
41		if exclusive {
42			if err := os.MkdirAll(s.root, 0o755); err != nil {
43				return err
44			}
45		}
46		lock, err := os.OpenFile(s.lockPath(), os.O_CREATE|os.O_RDWR, 0o644)
47		if err != nil {
48			return err
49		}
50		defer lock.Close()
51		mode := syscall.LOCK_SH
52		if exclusive {
53			mode = syscall.LOCK_EX
54		}
55		if err := syscall.Flock(int(lock.Fd()), mode); err != nil {
56			return err
57		}
58		defer syscall.Flock(int(lock.Fd()), syscall.LOCK_UN)
59		return fn()
60	}
61	
62	func (s *Store) Init() error {
63		return s.withLock(true, s.initLocked)
64	}
65	
66	func (s *Store) initLocked() error {
67		if err := os.MkdirAll(filepath.Join(s.root, "objects"), 0o755); err != nil {
68			return err
69		}
70		_, err := os.Stat(s.indexPath())
71		if errors.Is(err, os.ErrNotExist) {
72			return s.save(index{Entries: map[string]Entry{}})
73		}
74		return err
75	}
76	
77	func (s *Store) Put(name, source string) (Entry, error) {
78		if err := validateName(name); err != nil {
79			return Entry{}, err
80		}
81		if source == "" {
82			return Entry{}, errors.New("file is required")
83		}
84		var entry Entry
85		err := s.withLock(true, func() error {
86			if err := s.initLocked(); err != nil {
87				return err
88			}
89			in, err := os.Open(source)
90			if err != nil {
91				return err
92			}
93			defer in.Close()
94			tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".upload-*")
95			if err != nil {
96				return err
97			}
98			tmpName := tmp.Name()
99			defer os.Remove(tmpName)
100			hash := sha256.New()
101			size, copyErr := io.Copy(io.MultiWriter(tmp, hash), in)
102			closeErr := tmp.Close()
103			if copyErr != nil {
104				return copyErr
105			}
106			if closeErr != nil {
107				return closeErr
108			}
109			digest := hex.EncodeToString(hash.Sum(nil))
110			object := s.objectPath(digest)
111			if _, err := os.Stat(object); errors.Is(err, os.ErrNotExist) {
112				if err := os.Rename(tmpName, object); err != nil {
113					return err
114				}
115			}
116			idx, err := s.load()
117			if err != nil {
118				return err
119			}
120			entry = Entry{Name: name, Digest: digest, Size: size, CreatedAt: time.Now().UTC()}
121			idx.Entries[name] = entry
122			return s.save(idx)
123		})
124		if err != nil {
125			return Entry{}, err
126		}
127		return entry, nil
128	}
129	
130	func (s *Store) Get(name, output string) error {
131		if err := validateName(name); err != nil {
132			return err
133		}
134		if output == "" {
135			return errors.New("output is required")
136		}
137		return s.withLock(false, func() error {
138			idx, err := s.load()
139			if err != nil {
140				return err
141			}
142			entry, ok := idx.Entries[name]
143			if !ok {
144				return fmt.Errorf("artifact %q not found", name)
145			}
146			in, err := os.Open(s.objectPath(entry.Digest))
147			if err != nil {
148				return err
149			}
150			defer in.Close()
151			out, err := os.Create(output)
152			if err != nil {
153				return err
154			}
155			_, copyErr := io.Copy(out, in)
156			closeErr := out.Close()
157			if copyErr != nil {
158				return copyErr
159			}
160			return closeErr
161		})
162	}
163	
164	func (s *Store) List() ([]Entry, error) {
165		var entries []Entry
166		err := s.withLock(false, func() error {
167			idx, err := s.load()
168			if err != nil {
169				return err
170			}
171			entries = make([]Entry, 0, len(idx.Entries))
172			for _, entry := range idx.Entries {
173				entries = append(entries, entry)
174			}
175			return nil
176		})
177		if err != nil {
178			return nil, err
179		}
180		sort.Slice(entries, func(i, j int) bool { return entries[i].Name < entries[j].Name })
181		return entries, nil
182	}
183	
184	func (s *Store) Verify() (int, error) {
185		entries, err := s.List()
186		if err != nil {
187			return 0, err
188		}
189		for _, entry := range entries {
190			if err := s.verifyObject(entry); err != nil {
191				return 0, fmt.Errorf("verify %q: %w", entry.Name, err)
192			}
193		}
194		return len(entries), nil
195	}
196	
197	// verifyObject checks that the content object for entry exists and that its
198	// actual size and SHA-256 match the recorded metadata.
199	func (s *Store) verifyObject(entry Entry) error {
200		file, err := os.Open(s.objectPath(entry.Digest))
201		if err != nil {
202			return err
203		}
204		hash := sha256.New()
205		size, copyErr := io.Copy(hash, file)
206		closeErr := file.Close()
207		if copyErr != nil || closeErr != nil {
208			return errors.New("read failed")
209		}
210		if size != entry.Size || hex.EncodeToString(hash.Sum(nil)) != entry.Digest {
211			return errors.New("content mismatch")
212		}
213		return nil
214	}
215	
216	func (s *Store) load() (index, error) {
217		data, err := os.ReadFile(s.indexPath())
218		if err != nil {
219			return index{}, err
220		}
221		var idx index
222		if err := json.Unmarshal(data, &idx); err != nil {
223			return index{}, err
224		}
225		if idx.Entries == nil {
226			idx.Entries = map[string]Entry{}
227		}
228		return idx, nil
229	}
230	
231	func (s *Store) save(idx index) error {
232		data, err := json.MarshalIndent(idx, "", "  ")
233		if err != nil {
234			return err
235		}
236		data = append(data, '\n')
237		tmp, err := os.CreateTemp(s.root, ".index-*")
238		if err != nil {
239			return err
240		}
241		tmpName := tmp.Name()
242		defer os.Remove(tmpName)
243		if _, err := tmp.Write(data); err != nil {
244			tmp.Close()
245			return err
246		}
247		if err := tmp.Close(); err != nil {
248			return err
249		}
250		return os.Rename(tmpName, s.indexPath())
251	}
252	
253	func (s *Store) indexPath() string               { return filepath.Join(s.root, "index.json") }
254	func (s *Store) lockPath() string                { return filepath.Join(s.root, ".lock") }
255	func (s *Store) objectPath(digest string) string { return filepath.Join(s.root, "objects", digest) }
256	
257	func validateName(name string) error {
258		if strings.TrimSpace(name) == "" || filepath.IsAbs(name) || name == "." || name == ".." || strings.HasPrefix(name, "../") || strings.Contains(name, "\\") {
259			return errors.New("name must be a nonempty relative slash-separated path")
260		}
261		clean := filepath.Clean(name)
262		if clean != name || strings.HasPrefix(clean, "../") {
263			return errors.New("name must be normalized and remain within the vault namespace")
264		}
265		return nil
266	}
