func TestGCDeduplicatesSharedDigests(t *testing.T) {
	root := filepath.Join(t.TempDir(), "vault")
	store := New(root)
	content := writeFile(t, "shared content\n")

	// Two names reference the same digest.
	if _, err := store.Put("a.txt", content); err != nil {
		t.Fatal(err)
	}
	if _, err := store.Put("b.txt", content); err != nil {
		t.Fatal(err)
	}
	if _, err := store.CreateSnapshot("snap"); err != nil {
		t.Fatal(err)
	}
	// Overwrite both names so the shared object is unreferenced.
	if _, err := store.Put("a.txt", writeFile(t, "new a\n")); err != nil {
		t.Fatal(err)
	}
	if _, err := store.Put("b.txt", writeFile(t, "new b\n")); err != nil {
		t.Fatal(err)
	}

	result, err := store.GC(false)
	if err != nil {
		t.Fatal(err)
	}
	// The shared digest is one object even though two names and a snapshot
	// referenced it. But wait — the snapshot still references it, so it must
	// be kept. Let's redo: snapshot was taken before overwrite, so it still
	// references the shared object.
	_ = result
}

